// CSD_RATIONALE_BEGIN
// Root cause of 52% ceiling: premature IsCompletePrefix closure on short SQL.
// After generating "SELECT city", IsCompletePrefix fires immediately and the
// best 52% strategy (attempt 43) closes the span — returning semantically wrong
// SQL that is missing FROM/WHERE/GROUP BY/HAVING. The model, if allowed to
// continue generating under hard parser control with schema-token boosting,
// would naturally prefer emitting "FROM employee WHERE age < 30 GROUP BY..."
// over EOS because those tokens get +6.0 boost from validTokenGroups.
//
// Fix: Remove the in-loop IsCompletePrefix→CloseConstrainedSpan. Phase 3
// generates under GroupBoostedConstrainedStep(6.0) until the model emits EOS
// (natural stopping signal) or until the reserved budget for Phase 4 kicks in.
// Phase 4 uses CloseSpanWithinBudget(remaining ≤ 200), which internally tracks
// the longest complete prefix seen during generation and closes there.
//
// Everything else unchanged from best 52% attempt 43:
//   - RenderedEndsWith for delimiter detection (not exact token equality)
//   - 5-step unconstrained preamble to emit "SQL: "
//   - Force OpenConstrainedSpan if not entered naturally
//   - GroupBoostedConstrainedStep(6.0) for hard parser + schema preference
//   - EOS-triggered CloseConstrainedSpan when parser.IsCompletePrefix holds
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1: The only way insideConstrainedOut flips to true is via
//   RenderedEndsWith(generated, "<<"), at which point currentConstrainedOut
//   is set to [] and parser.IsValidPrefix([]) holds by method precondition.
//   EOS break leaves insideConstrainedOut=false; implication is vacuous.
//
// Phase 2: OpenConstrainedSpan sets currentConstrainedOut := [];
//   IsValidPrefix([]) holds by precondition.
//
// Phase 3 loop:
//   Non-EOS branch: GroupBoostedConstrainedStep hard-masks to parser-valid
//   tokens plus EOS, so next satisfies IsValidPrefix(currentConstrainedOut+[next]).
//   AppendConstrainedToken extends both generated and currentConstrainedOut by
//   next; parser validity is monotone under extension.
//   EOS+close branch: CloseConstrainedSpan sets insideConstrainedOut := false;
//   implication becomes vacuously true.
//   EOS+no-close branch: state unchanged, invariant preserved by induction.
//
// Phase 4: CloseSpanWithinBudget postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut) and !insideOut ==> currentOut == [].
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs +1 step; appends 0 (EOS) or 1 token.
//   Growth ≤ 1 token per +1 step; invariant preserved each iteration.
//
// Phase 2: OpenConstrainedSpan costs +1 step; appends exactly 1 "<<" token.
//   Strict 1:1; invariant preserved.
//
// Phase 3 loop:
//   Non-EOS: GroupBoostedConstrainedStep costs +1 step; AppendConstrainedToken
//   appends +1 token. Strict 1:1 ratio; invariant preserved.
//   EOS+close: +1 step (EOS) and +1 step (close) for at most +1 token (">>").
//   Net: ≤ 1 token per 2 steps; invariant strictly improves.
//   EOS+no-close: +1 step, 0 tokens; invariant strictly improves.
//
// Phase 4: CloseSpanWithinBudget postcondition |generatedOut| ≤ |generated| + closeBudget;
//   steps_out = steps_in + closeBudget; so |generated_out| ≤ |generatedPrefix| + steps_out. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. Always include FROM clause with exact table name. Include WHERE, GROUP BY, HAVING, ORDER BY LIMIT clauses when needed by the question. Use COUNT(*) for total counts. No table aliases. Output the SQL between << and >>.");

var steps: nat := 0;

